        total = 0
        is_negative = x < 0
        x = abs(x)

        while x > 0:
            total += x % 10
            x //= 10

        return total if not is_negative else -total + 1  # Adjusting for the signed first digit

    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1

    return count

